import{_ as a,o as e,c as r,ae as d}from"./chunks/framework.DNEY8DPf.js";const o="/cjrepo/docs/assets/admin_teams.png",i="/cjrepo/docs/assets/admin_team_members.png",s="/cjrepo/docs/assets/admin_team_orgs.png",l="/cjrepo/docs/assets/admin_team_packages.png",g=JSON.parse('{"title":"团队权限","description":"","frontmatter":{},"headers":[],"relativePath":"guide/teams.md","filePath":"guide/teams.md"}'),h={name:"guide/teams.md"};function n(c,t,p,m,b,_){return e(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="团队权限" tabindex="-1">团队权限 <a class="header-anchor" href="#团队权限" aria-label="Permalink to &quot;团队权限&quot;">​</a></h1><p>团队是 CJRepo 的权限管理核心。权限采用 <strong>双路径模型</strong>。</p><h2 id="权限级别" tabindex="-1">权限级别 <a class="header-anchor" href="#权限级别" aria-label="Permalink to &quot;权限级别&quot;">​</a></h2><table tabindex="0"><thead><tr><th>级别</th><th>说明</th></tr></thead><tbody><tr><td><code>read</code></td><td>可下载包和查看索引</td></tr><tr><td><code>write</code></td><td>可发布新版本</td></tr><tr><td><code>overwrite</code></td><td>可覆盖已存在的版本</td></tr></tbody></table><h2 id="双路径模型" tabindex="-1">双路径模型 <a class="header-anchor" href="#双路径模型" aria-label="Permalink to &quot;双路径模型&quot;">​</a></h2><h3 id="路径-1-个人发布-无组织包" tabindex="-1">路径 1：个人发布（无组织包） <a class="header-anchor" href="#路径-1-个人发布-无组织包" aria-label="Permalink to &quot;路径 1：个人发布（无组织包）&quot;">​</a></h3><p>任意有效 Token 即可发布无组织包，首次发布者自动成为 publisher：</p><table tabindex="0"><thead><tr><th>操作</th><th>规则</th></tr></thead><tbody><tr><td>发布新包</td><td>✅ 任意有效 Token 即可</td></tr><tr><td>发布新版本</td><td>✅ publisher 自动获得 write 权限</td></tr><tr><td>覆盖版本</td><td>❌ 需团队 overwrite 权限</td></tr></tbody></table><h3 id="路径-2-团队管理" tabindex="-1">路径 2：团队管理 <a class="header-anchor" href="#路径-2-团队管理" aria-label="Permalink to &quot;路径 2：团队管理&quot;">​</a></h3><p>团队通过组织关联或包关联获得权限控制：</p><table tabindex="0"><thead><tr><th>操作</th><th>规则</th></tr></thead><tbody><tr><td>发布新包（有组织）</td><td>❌ 必须有团队关联了该组织</td></tr><tr><td>发布新版本</td><td>✅ 团队关联了该 org/pkg 且权限 &gt;= write</td></tr><tr><td>覆盖版本</td><td>✅ 团队关联了该 org/pkg 且权限 &gt;= overwrite</td></tr></tbody></table><h2 id="管理界面" tabindex="-1">管理界面 <a class="header-anchor" href="#管理界面" aria-label="Permalink to &quot;管理界面&quot;">​</a></h2><p><img src="'+o+'" alt="团队列表"></p><h3 id="成员管理" tabindex="-1">成员管理 <a class="header-anchor" href="#成员管理" aria-label="Permalink to &quot;成员管理&quot;">​</a></h3><p>搜索用户并添加到团队：</p><p><img src="'+i+'" alt="团队成员"></p><h3 id="组织关联" tabindex="-1">组织关联 <a class="header-anchor" href="#组织关联" aria-label="Permalink to &quot;组织关联&quot;">​</a></h3><p>搜索组织并关联到团队，团队获得该组织下所有包的管理权：</p><p><img src="'+s+'" alt="组织关联"></p><h3 id="包关联" tabindex="-1">包关联 <a class="header-anchor" href="#包关联" aria-label="Permalink to &quot;包关联&quot;">​</a></h3><p>搜索包并关联到团队（支持 <code>org::keyword</code> 格式），团队获得该包的独立管理权。权限继承自团队默认级别：</p><p><img src="'+l+'" alt="包关联"></p><h2 id="管理团队" tabindex="-1">管理团队 <a class="header-anchor" href="#管理团队" aria-label="Permalink to &quot;管理团队&quot;">​</a></h2><ol><li>进入管理后台 → 团队管理</li><li>创建团队，设置默认权限（read/write/overwrite）</li><li>添加成员（搜索用户）</li><li>关联组织——团队获得该组织下所有包的管理权</li><li>关联具体包——团队获得特定包的管理权（权限继承自团队默认级别）</li></ol>',24)])])}const q=a(h,[["render",n]]);export{g as __pageData,q as default};
